
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_mggac_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_mggac", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.276814402734223e-02, -8.179112157682907e-02, -8.038671705106938e-02, -7.836834014797109e-02, -7.546824470983043e-02, -7.130338068272540e-02, -6.533327246532554e-02, -5.684068091472769e-02, -4.514050378076045e-02, -3.115105677069170e-02, -2.435215386306118e-02, -4.788860931842296e-02, -5.135360238770077e-02, -4.105699417426794e-02, -2.620785671029474e-02, -9.635003003135852e-03, -8.435484775894216e-04, -8.931768533029416e-06, -9.347895214884673e-09, -3.703691716373366e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


